import{c as e,S as t,j as r,m as i}from"./chunks/framework.VsSDrsS3.js";const d=JSON.parse('{"title":"AI 编程 & 工具","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/ai/ai-tools.md","filePath":"knowledge/ai/ai-tools.md","lastUpdated":1780046787000}'),l={name:"knowledge/ai/ai-tools.md"};function n(o,a,s,h,p,g){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="ai-编程-工具" tabindex="-1">AI 编程 &amp; 工具 <a class="header-anchor" href="#ai-编程-工具" aria-label="Permalink to “AI 编程 &amp; 工具”">​</a></h1><h2 id="浅谈-ai-编程的发展和未来" tabindex="-1">浅谈 AI 编程的发展和未来 <a class="header-anchor" href="#浅谈-ai-编程的发展和未来" aria-label="Permalink to “浅谈 AI 编程的发展和未来”">​</a></h2><p><strong>来源：</strong> AWS 官方博客</p><p><strong>核心观点：</strong></p><ul><li>AI 编程经历了三代：代码补全 → 对话式编程 → 自主 Agent</li><li>当前 GitHub Copilot 属于第二代（上下文感知补全），Devin/Cursor Agent 属于第三代（可自主执行任务）</li><li>AI 不会取代程序员，但会改变工作方式：程序员从&quot;写代码&quot;变成&quot;审查 AI 写的代码&quot;</li><li>未来趋势：AI 处理重复性工作（CRUD、样板代码），人处理创造性工作（架构、设计决策、疑难 Debug）</li></ul><h2 id="ai-应用无代码开发教程-工作流模式详解" tabindex="-1">AI 应用无代码开发教程：工作流模式详解 <a class="header-anchor" href="#ai-应用无代码开发教程-工作流模式详解" aria-label="Permalink to “AI 应用无代码开发教程：工作流模式详解”">​</a></h2><p><strong>来源：</strong> 阮一峰 — <em>科技爱好者周刊第 311 期</em></p><p><strong>知识点：</strong></p><ul><li>AI 工作流 = 把一个大任务拆成多个小步骤，每个步骤由 AI 执行，步骤之间可以串联/并联/条件分支</li><li>常见平台：Dify、Coze、n8n、LangChain</li><li>低利率时代适合做长期项目：技术基础设施、知识库建设、社区运营</li><li>&quot;长期项目在低利率时代更有价值&quot;——因为未来现金流折现更低</li></ul><h2 id="用-canvaskit-实现超级丝滑的原神地图" tabindex="-1">用 canvaskit 实现超级丝滑的原神地图 <a class="header-anchor" href="#用-canvaskit-实现超级丝滑的原神地图" aria-label="Permalink to “用 canvaskit 实现超级丝滑的原神地图”">​</a></h2><p><strong>知识点：</strong></p><ul><li>CanvasKit 是 Skia 图形引擎的 WASM 版本（Google 出品，Flutter 底层也用它）</li><li>相比 DOM/CSS 渲染，CanvasKit 直接用 GPU 绘制，性能远超传统方案</li><li>适合大量图形元素（如地图标注、粒子效果）的 Web 应用</li><li>WASM 加载体积较大（~3MB），需配合 CDN 和缓存策略</li></ul><h2 id="ai-工具平台" tabindex="-1">AI 工具平台 <a class="header-anchor" href="#ai-工具平台" aria-label="Permalink to “AI 工具平台”">​</a></h2><ul><li><strong><a href="https://www.coze.cn/" target="_blank" rel="noreferrer">扣子 Coze</a></strong> — 字节跳动 AI Agent 平台，零代码搭建 AI Bot，支持知识库 + 插件 + 工作流</li><li><strong><a href="https://platform.deepseek.com/usage" target="_blank" rel="noreferrer">DeepSeek 开放平台</a></strong> — 国产大模型 API，性价比极高，兼容 OpenAI SDK</li><li><strong><a href="https://aippy.ai/" target="_blank" rel="noreferrer">Aippy</a></strong> — AI 工作流自动化</li><li><strong><a href="https://www.minimaxi.com/" target="_blank" rel="noreferrer">MiniMax</a></strong> — 国内大模型，语音合成和视频生成见长</li><li><strong><a href="https://project-genie.ai/zh" target="_blank" rel="noreferrer">Project Genie</a></strong> — AI 3D 场景生成</li></ul>',14)])])}const A=e(l,[["render",n]]);export{d as __pageData,A as default};
